// Obtenemos el valor de 'respuesta_definitiva' desde el input
const respuestaDefinitiva = $('Webhook').first().json.body.custom_fields.respuesta_definitiva || '';

// Función para separar el texto y detectar múltiples enlaces
function separarMensaje(texto) {
    // Si no hay texto, devolvemos valores vacíos
    if (!texto) {
        return {
            texto: '',
            audio: []
        };
    }

    // Expresión regular para detectar URLs
    const urlRegex = /https:\/\/manybot-files\.s3\.eu-central-1\.amazonaws\.com\/[^,\s]+/g;
    const matches = texto.match(urlRegex) || []; // Obtenemos todas las coincidencias

    // Extraemos el texto eliminando los enlaces y comas, y limpiando espacios
    const textoLimpio = texto
        .replace(urlRegex, '') // Eliminamos los enlaces
        .replace(/,/g, '') // Eliminamos comas
        .trim(); // Limpiamos espacios

    return {
        texto: textoLimpio,
        audio: matches
    };
}

// Llamamos a la función y devolvemos el resultado
return separarMensaje(respuestaDefinitiva);

// Devuelve el Mensaje que coincide (contenido parcial o total) con
// $('Webhook').first().json.body.custom_fields.respuesta_definitiva

function limpiarTexto(t) {
  return String(t || '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

const webhookNode = $('Webhook').first();
const body = webhookNode && webhookNode.json && webhookNode.json.body;
const custom = body && body.custom_fields;
const rawRespuesta = custom && custom.respuesta_definitiva;

if (!rawRespuesta) {
  return [{ json: { resultado: null, motivo: 'No hay respuesta_definitiva' } }];
}

const resp = limpiarTexto(rawRespuesta);

// Recorremos todos los items de entrada
const items = $input.all();
for (const item of items) {
  const msg = item.json && item.json.Mensaje;
  if (!msg) continue;

  const msgClean = limpiarTexto(msg);

  // Coincidencia flexible: uno contenido en el otro
  if (resp.includes(msgClean) || msgClean.includes(resp)) {
    return [{
      json: {
        resultado: item.json.Mensaje,
        id: item.json.id || null
      }
    }];
  }
}

// Si no hay coincidencias
return [{ json: { resultado: null, motivo: 'No hubo coincidencia' } }];

